gr = GrammarRule.create!(id: 112, lesson_id: 27, number: 3, title: "GENITIVE WITH SLENDER CONSONANT", position: 3, created_at: "2026-04-11T22:46:59.610282Z", updated_at: "2026-04-11T22:46:59.610282Z")
