Exercise.create!(id: 133, lesson_id: 2, number: 8, prompt: "There is neither a door nor a lamp here.", answer: nil, created_at: "2026-04-11T22:28:24.376367Z", updated_at: "2026-04-11T22:28:24.376367Z")
Exercise.create!(id: 134, lesson_id: 2, number: 9, prompt: "I am satisfied now.", answer: nil, created_at: "2026-04-11T22:28:24.377025Z", updated_at: "2026-04-11T22:28:24.377025Z")
Exercise.create!(id: 135, lesson_id: 2, number: 10, prompt: "Are you satisfied?", answer: nil, created_at: "2026-04-11T22:28:24.377431Z", updated_at: "2026-04-11T22:28:24.377431Z")
Exercise.create!(id: 136, lesson_id: 2, number: 11, prompt: "He says that they are here too.", answer: nil, created_at: "2026-04-11T22:28:24.377809Z", updated_at: "2026-04-11T22:28:24.377809Z")
Exercise.create!(id: 137, lesson_id: 2, number: 12, prompt: "We are satisfied, but are you (pl) satisfied?", answer: nil, created_at: "2026-04-11T22:28:24.378183Z", updated_at: "2026-04-11T22:28:24.378183Z")
Exercise.create!(id: 138, lesson_id: 2, number: 13, prompt: "There are teachers and other people too.", answer: nil, created_at: "2026-04-11T22:28:24.378561Z", updated_at: "2026-04-11T22:28:24.378561Z")
Exercise.create!(id: 139, lesson_id: 2, number: 14, prompt: "You are not content but I am content.", answer: nil, created_at: "2026-04-11T22:28:24.378936Z", updated_at: "2026-04-11T22:28:24.378936Z")
Exercise.create!(id: 140, lesson_id: 2, number: 15, prompt: "One is content there.", answer: nil, created_at: "2026-04-11T22:28:24.379314Z", updated_at: "2026-04-11T22:28:24.379314Z")
Exercise.create!(id: 141, lesson_id: 3, number: 1, prompt: "There is a picture, a paper, a book and tables here.", answer: nil, created_at: "2026-04-11T22:28:51.723193Z", updated_at: "2026-04-11T22:28:51.723193Z")
Exercise.create!(id: 142, lesson_id: 3, number: 2, prompt: "Páidín's boat is there and there is a map here.", answer: nil, created_at: "2026-04-11T22:28:51.723713Z", updated_at: "2026-04-11T22:28:51.723713Z")
Exercise.create!(id: 143, lesson_id: 3, number: 3, prompt: "Neither the people of America nor the people of England are satisfied now.", answer: nil, created_at: "2026-04-11T22:28:51.724409Z", updated_at: "2026-04-11T22:28:51.724409Z")
Exercise.create!(id: 144, lesson_id: 3, number: 4, prompt: "Donncha's girl and Peige's husband are there.", answer: nil, created_at: "2026-04-11T22:28:51.724876Z", updated_at: "2026-04-11T22:28:51.724876Z")
Exercise.create!(id: 145, lesson_id: 3, number: 5, prompt: "The farmers of Kerry are not pleased and the farmers of Conamara are not content either.", answer: nil, created_at: "2026-04-11T22:28:51.725342Z", updated_at: "2026-04-11T22:28:51.725342Z")
Exercise.create!(id: 146, lesson_id: 3, number: 6, prompt: "Seáinín's field is there and Seáinín's bull is there too. Diarmaid's house is here.", answer: nil, created_at: "2026-04-11T22:28:51.725820Z", updated_at: "2026-04-11T22:28:51.725820Z")
Exercise.create!(id: 147, lesson_id: 3, number: 7, prompt: "Tomáisín's people are pleased.", answer: nil, created_at: "2026-04-11T22:28:51.726290Z", updated_at: "2026-04-11T22:28:51.726290Z")
Exercise.create!(id: 148, lesson_id: 3, number: 8, prompt: "There are plenty of rooms here. Bairbre's uncle's room is also here.", answer: nil, created_at: "2026-04-11T22:28:51.726756Z", updated_at: "2026-04-11T22:28:51.726756Z")
Exercise.create!(id: 149, lesson_id: 3, number: 9, prompt: "Where is the Gaoth Sáile road?", answer: nil, created_at: "2026-04-11T22:28:51.727228Z", updated_at: "2026-04-11T22:28:51.727228Z")
Exercise.create!(id: 150, lesson_id: 3, number: 10, prompt: "There aren't any (news)papers here at all but there are other books.", answer: nil, created_at: "2026-04-11T22:28:51.727934Z", updated_at: "2026-04-11T22:28:51.727934Z")
Exercise.create!(id: 151, lesson_id: 4, number: 1, prompt: "There are lots of countries on the map.", answer: nil, created_at: "2026-04-11T22:29:26.762615Z", updated_at: "2026-04-11T22:29:26.762615Z")
Exercise.create!(id: 152, lesson_id: 4, number: 2, prompt: "Cáit, where is England?", answer: nil, created_at: "2026-04-11T22:29:26.763106Z", updated_at: "2026-04-11T22:29:26.763106Z")
Exercise.create!(id: 153, lesson_id: 4, number: 3, prompt: "There is a big window there and another nice window here.", answer: nil, created_at: "2026-04-11T22:29:26.763535Z", updated_at: "2026-04-11T22:29:26.763535Z")
Exercise.create!(id: 154, lesson_id: 4, number: 4, prompt: "It is nice now. It is beautiful.", answer: nil, created_at: "2026-04-11T22:29:26.763960Z", updated_at: "2026-04-11T22:29:26.763960Z")
Exercise.create!(id: 155, lesson_id: 4, number: 5, prompt: "There is a good man there and a good woman too.", answer: nil, created_at: "2026-04-11T22:29:26.764382Z", updated_at: "2026-04-11T22:29:26.764382Z")
Exercise.create!(id: 156, lesson_id: 4, number: 6, prompt: "There is good Irish here. There is no college at all.", answer: nil, created_at: "2026-04-11T22:29:26.764805Z", updated_at: "2026-04-11T22:29:26.764805Z")
Exercise.create!(id: 157, lesson_id: 4, number: 7, prompt: "Diarmaid, there is a big room there and there is also a fine harp.", answer: nil, created_at: "2026-04-11T22:29:26.765236Z", updated_at: "2026-04-11T22:29:26.765236Z")
Exercise.create!(id: 158, lesson_id: 4, number: 8, prompt: "There is a fine big window here.", answer: nil, created_at: "2026-04-11T22:29:26.765672Z", updated_at: "2026-04-11T22:29:26.765672Z")
Exercise.create!(id: 159, lesson_id: 4, number: 9, prompt: "There are lots of countries and nations.", answer: nil, created_at: "2026-04-11T22:29:26.766099Z", updated_at: "2026-04-11T22:29:26.766099Z")
Exercise.create!(id: 160, lesson_id: 4, number: 10, prompt: "Maybe Páidín's wife and Bríd's husband are here.", answer: nil, created_at: "2026-04-11T22:29:26.766523Z", updated_at: "2026-04-11T22:29:26.766523Z")
Exercise.create!(id: 161, lesson_id: 4, number: 11, prompt: "There is rain and cold.", answer: nil, created_at: "2026-04-11T22:29:26.766956Z", updated_at: "2026-04-11T22:29:26.766956Z")
Exercise.create!(id: 162, lesson_id: 4, number: 12, prompt: "There is a nice woman, and a priest, a big farmer and another tall Irish person here.", answer: nil, created_at: "2026-04-11T22:29:26.767391Z", updated_at: "2026-04-11T22:29:26.767391Z")
Exercise.create!(id: 163, lesson_id: 4, number: 13, prompt: "There is a big Gaeltacht here, in any case.", answer: nil, created_at: "2026-04-11T22:29:26.767815Z", updated_at: "2026-04-11T22:29:26.767815Z")
Exercise.create!(id: 164, lesson_id: 4, number: 14, prompt: "There is a fine place here and perhaps there is another one there.", answer: nil, created_at: "2026-04-11T22:29:26.768237Z", updated_at: "2026-04-11T22:29:26.768237Z")
Exercise.create!(id: 165, lesson_id: 4, number: 15, prompt: "We are here again. It is wonderful.", answer: nil, created_at: "2026-04-11T22:29:26.768645Z", updated_at: "2026-04-11T22:29:26.768645Z")
Exercise.create!(id: 166, lesson_id: 5, number: 1, prompt: "Brid's room is here. It is small but all the same it is nice.", answer: nil, created_at: "2026-04-11T22:29:56.652235Z", updated_at: "2026-04-11T22:29:56.652235Z")
Exercise.create!(id: 167, lesson_id: 5, number: 2, prompt: "There is a kitchen and it is big too.", answer: nil, created_at: "2026-04-11T22:29:56.652774Z", updated_at: "2026-04-11T22:29:56.652774Z")
Exercise.create!(id: 168, lesson_id: 5, number: 3, prompt: "The books are there on the floor. There are a lot on the table too.", answer: nil, created_at: "2026-04-11T22:29:56.653316Z", updated_at: "2026-04-11T22:29:56.653316Z")
Exercise.create!(id: 169, lesson_id: 5, number: 4, prompt: "Máire is on the phone. Where is the phone? It is there near the door.", answer: nil, created_at: "2026-04-11T22:29:56.653913Z", updated_at: "2026-04-11T22:29:56.653913Z")
Exercise.create!(id: 170, lesson_id: 5, number: 5, prompt: "There is food on the plate.", answer: nil, created_at: "2026-04-11T22:29:56.654469Z", updated_at: "2026-04-11T22:29:56.654469Z")
Exercise.create!(id: 171, lesson_id: 5, number: 6, prompt: "There are a few chairs near the fire.", answer: nil, created_at: "2026-04-11T22:29:56.655007Z", updated_at: "2026-04-11T22:29:56.655007Z")
Exercise.create!(id: 172, lesson_id: 5, number: 7, prompt: "There are books and papers on the chair.", answer: nil, created_at: "2026-04-11T22:29:56.655537Z", updated_at: "2026-04-11T22:29:56.655537Z")
Exercise.create!(id: 173, lesson_id: 5, number: 8, prompt: "Máirtín's hand is on the glass.", answer: nil, created_at: "2026-04-11T22:29:56.656063Z", updated_at: "2026-04-11T22:29:56.656063Z")
Exercise.create!(id: 174, lesson_id: 5, number: 9, prompt: "Are you satisfied with the nation?", answer: nil, created_at: "2026-04-11T22:29:56.656582Z", updated_at: "2026-04-11T22:29:56.656582Z")
Exercise.create!(id: 175, lesson_id: 5, number: 10, prompt: "There is a teaspoon on the saucer.", answer: nil, created_at: "2026-04-11T22:29:56.657075Z", updated_at: "2026-04-11T22:29:56.657075Z")
Exercise.create!(id: 176, lesson_id: 5, number: 11, prompt: "They are not satisfied with the teacher at all.", answer: nil, created_at: "2026-04-11T22:29:56.657594Z", updated_at: "2026-04-11T22:29:56.657594Z")
Exercise.create!(id: 177, lesson_id: 5, number: 12, prompt: "The nice place is on the map.", answer: nil, created_at: "2026-04-11T22:29:56.658117Z", updated_at: "2026-04-11T22:29:56.658117Z")
Exercise.create!(id: 178, lesson_id: 5, number: 13, prompt: "Is there French there?", answer: nil, created_at: "2026-04-11T22:29:56.658641Z", updated_at: "2026-04-11T22:29:56.658641Z")
Exercise.create!(id: 179, lesson_id: 5, number: 14, prompt: "There is good French there.", answer: nil, created_at: "2026-04-11T22:29:56.659163Z", updated_at: "2026-04-11T22:29:56.659163Z")
Exercise.create!(id: 180, lesson_id: 6, number: 1, prompt: "Dublin will be wonderful tomorrow.", answer: nil, created_at: "2026-04-11T22:30:39.938003Z", updated_at: "2026-04-11T22:30:39.938003Z")
Exercise.create!(id: 181, lesson_id: 6, number: 2, prompt: "I was a week there last year.", answer: nil, created_at: "2026-04-11T22:30:39.938439Z", updated_at: "2026-04-11T22:30:39.938439Z")
Exercise.create!(id: 182, lesson_id: 6, number: 3, prompt: "Were you (pl.) sick yesterday?", answer: nil, created_at: "2026-04-11T22:30:39.938872Z", updated_at: "2026-04-11T22:30:39.938872Z")
Exercise.create!(id: 183, lesson_id: 6, number: 4, prompt: "Will you be here tomorrow? We will be here certainly, at any rate.", answer: nil, created_at: "2026-04-11T22:30:39.939293Z", updated_at: "2026-04-11T22:30:39.939293Z")
Exercise.create!(id: 184, lesson_id: 6, number: 5, prompt: "He is not sure whether he will be here again or not.", answer: nil, created_at: "2026-04-11T22:30:39.939726Z", updated_at: "2026-04-11T22:30:39.939726Z")
Exercise.create!(id: 185, lesson_id: 6, number: 6, prompt: "The woman had a big house and there were lots of rooms.", answer: nil, created_at: "2026-04-11T22:30:39.940351Z", updated_at: "2026-04-11T22:30:39.940351Z")
Exercise.create!(id: 186, lesson_id: 6, number: 7, prompt: "Were there books and papers on the table? - Yes, indeed.", answer: nil, created_at: "2026-04-11T22:30:39.940777Z", updated_at: "2026-04-11T22:30:39.940777Z")
Exercise.create!(id: 187, lesson_id: 6, number: 8, prompt: "Máire also has a nice coat and a wonderful dress. - Yes, she has indeed.", answer: nil, created_at: "2026-04-11T22:30:39.941195Z", updated_at: "2026-04-11T22:30:39.941195Z")
Exercise.create!(id: 188, lesson_id: 6, number: 9, prompt: "Were there many people? Was one (were people) satisfied with the place?", answer: nil, created_at: "2026-04-11T22:30:39.941615Z", updated_at: "2026-04-11T22:30:39.941615Z")
Exercise.create!(id: 189, lesson_id: 6, number: 10, prompt: "There will be lots and lots (go leor leor) of cars and buses on the road but there won't be many trees.", answer: nil, created_at: "2026-04-11T22:30:39.942031Z", updated_at: "2026-04-11T22:30:39.942031Z")
Exercise.create!(id: 190, lesson_id: 6, number: 11, prompt: "There were a few people at the gate again, so Cáit was pleased.", answer: nil, created_at: "2026-04-11T22:30:39.942637Z", updated_at: "2026-04-11T22:30:39.942637Z")
Exercise.create!(id: 191, lesson_id: 6, number: 12, prompt: "Diarmaid has a nice shirt, hasn't he?", answer: nil, created_at: "2026-04-11T22:30:39.943049Z", updated_at: "2026-04-11T22:30:39.943049Z")
Exercise.create!(id: 192, lesson_id: 6, number: 13, prompt: "There was a street on the other side but there weren't many people.", answer: nil, created_at: "2026-04-11T22:30:39.943455Z", updated_at: "2026-04-11T22:30:39.943455Z")
Exercise.create!(id: 193, lesson_id: 6, number: 14, prompt: "Peige's father and mother were fairly pleased with the picture.", answer: nil, created_at: "2026-04-11T22:30:39.943874Z", updated_at: "2026-04-11T22:30:39.943874Z")
Exercise.create!(id: 194, lesson_id: 6, number: 15, prompt: "There were shirts and pairs of trousers and lots of other clothes on the floor near the window.", answer: nil, created_at: "2026-04-11T22:30:39.944290Z", updated_at: "2026-04-11T22:30:39.944290Z")
Exercise.create!(id: 195, lesson_id: 7, number: 1, prompt: "Máirtín had small children.", answer: nil, created_at: "2026-04-11T22:31:18.437988Z", updated_at: "2026-04-11T22:31:18.437988Z")
Exercise.create!(id: 196, lesson_id: 7, number: 2, prompt: "There are nice big windows here.", answer: nil, created_at: "2026-04-11T22:31:18.438433Z", updated_at: "2026-04-11T22:31:18.438433Z")
Exercise.create!(id: 197, lesson_id: 7, number: 3, prompt: "There are big trees and nice fields here now but there will be houses and colleges here.", answer: nil, created_at: "2026-04-11T22:31:18.438846Z", updated_at: "2026-04-11T22:31:18.438846Z")
Exercise.create!(id: 198, lesson_id: 7, number: 4, prompt: "There used to be lots of cows and horses here but now there aren't many at all.", answer: nil, created_at: "2026-04-11T22:31:18.439261Z", updated_at: "2026-04-11T22:31:18.439261Z")
Exercise.create!(id: 199, lesson_id: 7, number: 5, prompt: "They used to be satisfied with the farm, usen't they?", answer: nil, created_at: "2026-04-11T22:31:18.439677Z", updated_at: "2026-04-11T22:31:18.439677Z")
Exercise.create!(id: 200, lesson_id: 7, number: 6, prompt: "The land usen't to be good here and there used to be too much water.", answer: nil, created_at: "2026-04-11T22:31:18.440098Z", updated_at: "2026-04-11T22:31:18.440098Z")
Exercise.create!(id: 201, lesson_id: 7, number: 7, prompt: "Would you be satisfied with the life on the farm? Yes, certainly, I would.", answer: nil, created_at: "2026-04-11T22:31:18.440522Z", updated_at: "2026-04-11T22:31:18.440522Z")
Exercise.create!(id: 202, lesson_id: 7, number: 8, prompt: "The summer and the winter would be nice here.", answer: nil, created_at: "2026-04-11T22:31:18.440945Z", updated_at: "2026-04-11T22:31:18.440945Z")
Exercise.create!(id: 203, lesson_id: 7, number: 9, prompt: "There were many rich people here.", answer: nil, created_at: "2026-04-11T22:31:18.441450Z", updated_at: "2026-04-11T22:31:18.441450Z")
Exercise.create!(id: 204, lesson_id: 7, number: 10, prompt: "I was there a few weeks last year and the weather was wonderful.", answer: nil, created_at: "2026-04-11T22:31:18.441866Z", updated_at: "2026-04-11T22:31:18.441866Z")
Exercise.create!(id: 205, lesson_id: 7, number: 11, prompt: "The woman has a son and a daughter.", answer: nil, created_at: "2026-04-11T22:31:18.442279Z", updated_at: "2026-04-11T22:31:18.442279Z")
Exercise.create!(id: 206, lesson_id: 7, number: 12, prompt: "Oh now, the poor thing! It is cold here again.", answer: nil, created_at: "2026-04-11T22:31:18.442691Z", updated_at: "2026-04-11T22:31:18.442691Z")
Exercise.create!(id: 207, lesson_id: 7, number: 13, prompt: "There are sheep and horses on the hill.", answer: nil, created_at: "2026-04-11T22:31:18.443113Z", updated_at: "2026-04-11T22:31:18.443113Z")
Exercise.create!(id: 208, lesson_id: 7, number: 14, prompt: "Ladies and gentlemen, is everybody satisfied with the place?", answer: nil, created_at: "2026-04-11T22:31:18.445797Z", updated_at: "2026-04-11T22:31:18.445797Z")
Exercise.create!(id: 209, lesson_id: 7, number: 15, prompt: "I am sure that the book wouldn't be interesting anyway.", answer: nil, created_at: "2026-04-11T22:31:18.446220Z", updated_at: "2026-04-11T22:31:18.446220Z")
Exercise.create!(id: 210, lesson_id: 8, number: 1, prompt: "Úna's heart was never good. She is dead now, the poor thing.", answer: nil, created_at: "2026-04-11T22:31:56.542233Z", updated_at: "2026-04-11T22:31:56.542233Z")
Exercise.create!(id: 211, lesson_id: 8, number: 2, prompt: "There is one child and he is still fairly young.", answer: nil, created_at: "2026-04-11T22:31:56.542646Z", updated_at: "2026-04-11T22:31:56.542646Z")
Exercise.create!(id: 212, lesson_id: 8, number: 3, prompt: "If Páidín is here in the evening, usually he is bad-humoured, especially with the child.", answer: nil, created_at: "2026-04-11T22:31:56.543047Z", updated_at: "2026-04-11T22:31:56.543047Z")
Exercise.create!(id: 213, lesson_id: 8, number: 4, prompt: "Don't be (pl.) bold like that! Be (pl.) quiet!", answer: nil, created_at: "2026-04-11T22:31:56.543446Z", updated_at: "2026-04-11T22:31:56.543446Z")
Exercise.create!(id: 214, lesson_id: 8, number: 5, prompt: "Usually we are tired in the evening.", answer: nil, created_at: "2026-04-11T22:31:56.544133Z", updated_at: "2026-04-11T22:31:56.544133Z")
Exercise.create!(id: 215, lesson_id: 8, number: 6, prompt: "If Seáinín was there, I am satisfied.", answer: nil, created_at: "2026-04-11T22:31:56.544538Z", updated_at: "2026-04-11T22:31:56.544538Z")
Exercise.create!(id: 216, lesson_id: 8, number: 7, prompt: "I see that the key is there on the table but I'm not sure where the door is.", answer: nil, created_at: "2026-04-11T22:31:56.544939Z", updated_at: "2026-04-11T22:31:56.544939Z")
Exercise.create!(id: 217, lesson_id: 8, number: 8, prompt: "If the apple is there tomorrow, Cáit will be pleased.", answer: nil, created_at: "2026-04-11T22:31:56.545348Z", updated_at: "2026-04-11T22:31:56.545348Z")
Exercise.create!(id: 218, lesson_id: 8, number: 9, prompt: "If the house isn't beside the school, Ruairí will be bad-humoured.", answer: nil, created_at: "2026-04-11T22:31:56.545747Z", updated_at: "2026-04-11T22:31:56.545747Z")
Exercise.create!(id: 219, lesson_id: 8, number: 10, prompt: "If you are here tomorrow, I'll be here too.", answer: nil, created_at: "2026-04-11T22:31:56.546192Z", updated_at: "2026-04-11T22:31:56.546192Z")
Exercise.create!(id: 220, lesson_id: 8, number: 11, prompt: "He was here one evening and he was sick.", answer: nil, created_at: "2026-04-11T22:31:56.546600Z", updated_at: "2026-04-11T22:31:56.546600Z")
Exercise.create!(id: 221, lesson_id: 8, number: 12, prompt: "If he is here in the evening everybody will be pleased.", answer: nil, created_at: "2026-04-11T22:31:56.547009Z", updated_at: "2026-04-11T22:31:56.547009Z")
Exercise.create!(id: 222, lesson_id: 9, number: 1, prompt: "The teacher was tired, but the farmer himself was there also.", answer: nil, created_at: "2026-04-11T22:32:33.854810Z", updated_at: "2026-04-11T22:32:33.854810Z")
Exercise.create!(id: 223, lesson_id: 9, number: 2, prompt: "I understand it now. The door is there and the keys are on the table.", answer: nil, created_at: "2026-04-11T22:32:33.855618Z", updated_at: "2026-04-11T22:32:33.855618Z")
Exercise.create!(id: 224, lesson_id: 9, number: 3, prompt: "Are you there? I see you now.", answer: nil, created_at: "2026-04-11T22:32:33.856035Z", updated_at: "2026-04-11T22:32:33.856035Z")
Exercise.create!(id: 225, lesson_id: 9, number: 4, prompt: "She says the whole crowd will be at the sea tomorrow, but I don't believe her at all.", answer: nil, created_at: "2026-04-11T22:32:33.856456Z", updated_at: "2026-04-11T22:32:33.856456Z")
Exercise.create!(id: 226, lesson_id: 9, number: 5, prompt: "I understand you well, but I don't understand those (people) at all.", answer: nil, created_at: "2026-04-11T22:32:33.856903Z", updated_at: "2026-04-11T22:32:33.856903Z")
Exercise.create!(id: 227, lesson_id: 9, number: 6, prompt: "They say that the mountains are there but I myself don't see them at all.", answer: nil, created_at: "2026-04-11T22:32:33.857334Z", updated_at: "2026-04-11T22:32:33.857334Z")
Exercise.create!(id: 228, lesson_id: 9, number: 7, prompt: "There is a mirror here. I see myself now.", answer: nil, created_at: "2026-04-11T22:32:33.857783Z", updated_at: "2026-04-11T22:32:33.857783Z")
Exercise.create!(id: 229, lesson_id: 9, number: 8, prompt: "You and I will be satisfied with the autumn and with the spring here.", answer: nil, created_at: "2026-04-11T22:32:33.858420Z", updated_at: "2026-04-11T22:32:33.858420Z")
Exercise.create!(id: 230, lesson_id: 9, number: 9, prompt: "Were you yourself at the library yesterday? You were? That is good. Were you there early in the morning?", answer: nil, created_at: "2026-04-11T22:32:33.858831Z", updated_at: "2026-04-11T22:32:33.858831Z")
Exercise.create!(id: 231, lesson_id: 9, number: 10, prompt: "'They' (siúd) would be satisfied with the public houses here.", answer: nil, created_at: "2026-04-11T22:32:33.859245Z", updated_at: "2026-04-11T22:32:33.859245Z")
Exercise.create!(id: 232, lesson_id: 9, number: 11, prompt: "The weather was good this year although there was snow on all the mountains.", answer: nil, created_at: "2026-04-11T22:32:33.859651Z", updated_at: "2026-04-11T22:32:33.859651Z")
Exercise.create!(id: 233, lesson_id: 9, number: 12, prompt: "We were a fortnight here last year but you (pl.) weren't there at all.", answer: nil, created_at: "2026-04-11T22:32:33.860062Z", updated_at: "2026-04-11T22:32:33.860062Z")
Exercise.create!(id: 234, lesson_id: 10, number: 1, prompt: "My mother and father were here last year.", answer: nil, created_at: "2026-04-11T22:33:11.801011Z", updated_at: "2026-04-11T22:33:11.801011Z")
Exercise.create!(id: 235, lesson_id: 10, number: 2, prompt: "Are your father and mother pleased with the new house?", answer: nil, created_at: "2026-04-11T22:33:11.801403Z", updated_at: "2026-04-11T22:33:11.801403Z")
Exercise.create!(id: 236, lesson_id: 10, number: 3, prompt: "My books are here but yours aren't here at all.", answer: nil, created_at: "2026-04-11T22:33:11.801796Z", updated_at: "2026-04-11T22:33:11.801796Z")
Exercise.create!(id: 237, lesson_id: 10, number: 4, prompt: "Our Irish is good but yours (pl.) is not good.", answer: nil, created_at: "2026-04-11T22:33:11.802191Z", updated_at: "2026-04-11T22:33:11.802191Z")
Exercise.create!(id: 238, lesson_id: 10, number: 5, prompt: "Your own milk is sour.", answer: nil, created_at: "2026-04-11T22:33:11.802604Z", updated_at: "2026-04-11T22:33:11.802604Z")
Exercise.create!(id: 239, lesson_id: 10, number: 6, prompt: "His room is here. Her room is there.", answer: nil, created_at: "2026-04-11T22:33:11.803093Z", updated_at: "2026-04-11T22:33:11.803093Z")
Exercise.create!(id: 240, lesson_id: 10, number: 7, prompt: "She was at 'that' fellow's house again yesterday.", answer: nil, created_at: "2026-04-11T22:33:11.803556Z", updated_at: "2026-04-11T22:33:11.803556Z")
Exercise.create!(id: 241, lesson_id: 10, number: 8, prompt: "Máirtín's clothes are always nice.", answer: nil, created_at: "2026-04-11T22:33:11.803973Z", updated_at: "2026-04-11T22:33:11.803973Z")
Exercise.create!(id: 242, lesson_id: 10, number: 9, prompt: "Unless her English was good her uncle wouldn't be at all pleased.", answer: nil, created_at: "2026-04-11T22:33:11.804860Z", updated_at: "2026-04-11T22:33:11.804860Z")
Exercise.create!(id: 243, lesson_id: 10, number: 10, prompt: "His mouth is sore and there is an ugly taste on his tongue.", answer: nil, created_at: "2026-04-11T22:33:11.805249Z", updated_at: "2026-04-11T22:33:11.805249Z")
Exercise.create!(id: 244, lesson_id: 10, number: 11, prompt: "If his finger was right, the doctor at the hospital would be pleased enough.", answer: nil, created_at: "2026-04-11T22:33:11.805623Z", updated_at: "2026-04-11T22:33:11.805623Z")
Exercise.create!(id: 245, lesson_id: 10, number: 12, prompt: "It isn't likely that I'll be long lodging here. The weather is bad. There is rain and wind and I don't see the sea or the islands at all.", answer: nil, created_at: "2026-04-11T22:33:11.806000Z", updated_at: "2026-04-11T22:33:11.806000Z")
Exercise.create!(id: 246, lesson_id: 10, number: 13, prompt: "If there was a Mass early on Sunday, the church wouldn't be full at all.", answer: nil, created_at: "2026-04-11T22:33:11.806370Z", updated_at: "2026-04-11T22:33:11.806370Z")
Exercise.create!(id: 247, lesson_id: 10, number: 14, prompt: "The doctor isn't here but he'll be back in a little while,\" says the nurse. \"There is fog and there was an accident on the road a while ago.\" His bag was on the table and there was a strange needle beside the bag.", answer: nil, created_at: "2026-04-11T22:33:11.807314Z", updated_at: "2026-04-11T22:33:11.807314Z")
Exercise.create!(id: 248, lesson_id: 10, number: 15, prompt: "The bottle isn't full but I have enough here.", answer: nil, created_at: "2026-04-11T22:33:11.807691Z", updated_at: "2026-04-11T22:33:11.807691Z")
Exercise.create!(id: 249, lesson_id: 10, number: 16, prompt: "This language isn't difficult but they say that yours is difficult enough.", answer: nil, created_at: "2026-04-11T22:33:11.808062Z", updated_at: "2026-04-11T22:33:11.808062Z")
Exercise.create!(id: 250, lesson_id: 11, number: 1, prompt: "thú Seáinín ?", answer: nil, created_at: "2026-04-11T22:34:00.473285Z", updated_at: "2026-04-11T22:34:00.473285Z")
