Exercise.create!(id: 256, lesson_id: 11, number: 7, prompt: "an múinteoir é ?", answer: nil, created_at: "2026-04-11T22:34:00.476363Z", updated_at: "2026-04-11T22:34:00.476363Z")
Exercise.create!(id: 257, lesson_id: 11, number: 8, prompt: "do mháthair í ?", answer: nil, created_at: "2026-04-11T22:34:00.476774Z", updated_at: "2026-04-11T22:34:00.476774Z")
