Exercise.create!(id: 259, lesson_id: 11, number: 10, prompt: "thú Donncha ?", answer: nil, created_at: "2026-04-11T22:34:00.477585Z", updated_at: "2026-04-11T22:34:00.477585Z")
Exercise.create!(id: 260, lesson_id: 11, number: 11, prompt: "Bríd do bhean ?", answer: nil, created_at: "2026-04-11T22:34:00.478610Z", updated_at: "2026-04-11T22:34:00.478610Z")
Exercise.create!(id: 261, lesson_id: 11, number: 12, prompt: "na múinteoirí iad ?", answer: nil, created_at: "2026-04-11T22:34:00.479011Z", updated_at: "2026-04-11T22:34:00.479011Z")
Exercise.create!(id: 262, lesson_id: 11, number: 13, prompt: "an fear mór sin t'athair ?", answer: nil, created_at: "2026-04-11T22:34:00.479413Z", updated_at: "2026-04-11T22:34:00.479413Z")
Exercise.create!(id: 263, lesson_id: 11, number: 14, prompt: "sin do dheirfiúr ?", answer: nil, created_at: "2026-04-11T22:34:00.479813Z", updated_at: "2026-04-11T22:34:00.479813Z")
Exercise.create!(id: 264, lesson_id: 11, number: 15, prompt: "thusa Cáit?", answer: nil, created_at: "2026-04-11T22:34:00.480230Z", updated_at: "2026-04-11T22:34:00.480230Z")
Exercise.create!(id: 265, lesson_id: 11, number: 16, prompt: "thú Pádraig?", answer: nil, created_at: "2026-04-11T22:34:00.480637Z", updated_at: "2026-04-11T22:34:00.480637Z")
Exercise.create!(id: 266, lesson_id: 11, number: 17, prompt: "do mháthair í?", answer: nil, created_at: "2026-04-11T22:34:00.481092Z", updated_at: "2026-04-11T22:34:00.481092Z")
Exercise.create!(id: 267, lesson_id: 11, number: 18, prompt: "féin an múinteoir ?", answer: nil, created_at: "2026-04-11T22:34:00.481550Z", updated_at: "2026-04-11T22:34:00.481550Z")
Exercise.create!(id: 268, lesson_id: 11, number: 19, prompt: "Marab é sin an múinteoir, níl sé anseo ar chor ar bith.", answer: nil, created_at: "2026-04-11T22:34:00.482624Z", updated_at: "2026-04-11T22:34:00.482624Z")
Exercise.create!(id: 269, lesson_id: 11, number: 20, prompt: "Deir siad é sin a uncail.", answer: nil, created_at: "2026-04-11T22:34:00.483027Z", updated_at: "2026-04-11T22:34:00.483027Z")
Exercise.create!(id: 270, lesson_id: 11, number: 21, prompt: "thusa Donncha, beidh Cáit sásta.", answer: nil, created_at: "2026-04-11T22:34:00.483439Z", updated_at: "2026-04-11T22:34:00.483439Z")
Exercise.create!(id: 271, lesson_id: 11, number: 22, prompt: "thusa Cáit, ní bheidh sé sásta ar chor ar bith.", answer: nil, created_at: "2026-04-11T22:34:00.483846Z", updated_at: "2026-04-11T22:34:00.483846Z")
Exercise.create!(id: 272, lesson_id: 11, number: 23, prompt: "Deir siad thusa Cáit.", answer: nil, created_at: "2026-04-11T22:34:00.484262Z", updated_at: "2026-04-11T22:34:00.484262Z")
Exercise.create!(id: 273, lesson_id: 11, number: 24, prompt: "ionann iad.", answer: nil, created_at: "2026-04-11T22:34:00.484701Z", updated_at: "2026-04-11T22:34:00.484701Z")
Exercise.create!(id: 274, lesson_id: 11, number: 25, prompt: "deas iad ?", answer: nil, created_at: "2026-04-11T22:34:00.485113Z", updated_at: "2026-04-11T22:34:00.485113Z")
Exercise.create!(id: 275, lesson_id: 13, number: 1, prompt: "Cáit has the same bad old car, the car Bríd had when she was here last year.", answer: nil, created_at: "2026-04-11T22:35:39.423991Z", updated_at: "2026-04-11T22:35:39.423991Z")
Exercise.create!(id: 276, lesson_id: 13, number: 2, prompt: "Who is there? - Me, open the door!", answer: nil, created_at: "2026-04-11T22:35:39.424387Z", updated_at: "2026-04-11T22:35:39.424387Z")
Exercise.create!(id: 277, lesson_id: 13, number: 3, prompt: "This place is exactly as it used to be when I used to be here a few years ago.", answer: nil, created_at: "2026-04-11T22:35:39.424917Z", updated_at: "2026-04-11T22:35:39.424917Z")
Exercise.create!(id: 278, lesson_id: 13, number: 4, prompt: "The bus is always early; as soon as you are at the shop, it is there.", answer: nil, created_at: "2026-04-11T22:35:39.425302Z", updated_at: "2026-04-11T22:35:39.425302Z")
Exercise.create!(id: 279, lesson_id: 13, number: 5, prompt: "My jumper is here but it is far too big.", answer: nil, created_at: "2026-04-11T22:35:39.425688Z", updated_at: "2026-04-11T22:35:39.425688Z")
Exercise.create!(id: 280, lesson_id: 13, number: 6, prompt: "All the neighbours were at the dance on Saturday. It was really good. There was music and songs.", answer: nil, created_at: "2026-04-11T22:35:39.426092Z", updated_at: "2026-04-11T22:35:39.426092Z")
Exercise.create!(id: 281, lesson_id: 13, number: 7, prompt: "People have the notion that the city is worse, especially around Christmas. I am sure that it is lonely at the weekend.", answer: nil, created_at: "2026-04-11T22:35:39.426485Z", updated_at: "2026-04-11T22:35:39.426485Z")
Exercise.create!(id: 282, lesson_id: 14, number: 1, prompt: "Tá mé in ann Gaeilge", answer: nil, created_at: "2026-04-11T22:36:20.655369Z", updated_at: "2026-04-11T22:36:20.655369Z")
Exercise.create!(id: 283, lesson_id: 14, number: 2, prompt: "Níl an crann in ann", answer: nil, created_at: "2026-04-11T22:36:20.655796Z", updated_at: "2026-04-11T22:36:20.655796Z")
Exercise.create!(id: 284, lesson_id: 14, number: 3, prompt: "An mbeifeá sásta an doras?", answer: nil, created_at: "2026-04-11T22:36:20.656233Z", updated_at: "2026-04-11T22:36:20.656233Z")
Exercise.create!(id: 285, lesson_id: 14, number: 4, prompt: "Tá sé deacair an scéal sin", answer: nil, created_at: "2026-04-11T22:36:20.656681Z", updated_at: "2026-04-11T22:36:20.656681Z")
Exercise.create!(id: 286, lesson_id: 14, number: 5, prompt: "Bhí mé sásta gan an leabhar sin", answer: nil, created_at: "2026-04-11T22:36:20.657094Z", updated_at: "2026-04-11T22:36:20.657094Z")
Exercise.create!(id: 287, lesson_id: 14, number: 6, prompt: "Tráthnóna Dé hAoine beidh muid in ann abhaile.", answer: nil, created_at: "2026-04-11T22:36:20.657511Z", updated_at: "2026-04-11T22:36:20.657511Z")
Exercise.create!(id: 288, lesson_id: 14, number: 7, prompt: "Tá sé go deas anseo.", answer: nil, created_at: "2026-04-11T22:36:20.657989Z", updated_at: "2026-04-11T22:36:20.657989Z")
Exercise.create!(id: 289, lesson_id: 14, number: 8, prompt: "Ní raibh doras ann agus b'éigean an fhuinneog", answer: nil, created_at: "2026-04-11T22:36:20.658411Z", updated_at: "2026-04-11T22:36:20.658411Z")
Exercise.create!(id: 290, lesson_id: 14, number: 9, prompt: "Bhí sé sásta gan anseo inniu, mar bhí mo mháthair tinn.", answer: nil, created_at: "2026-04-11T22:36:20.658817Z", updated_at: "2026-04-11T22:36:20.658817Z")
Exercise.create!(id: 291, lesson_id: 14, number: 10, prompt: "Tá Cáit sásta gan mar tá Máirtín ró-shean anois.", answer: nil, created_at: "2026-04-11T22:36:20.659221Z", updated_at: "2026-04-11T22:36:20.659221Z")
Exercise.create!(id: 292, lesson_id: 14, number: 11, prompt: "Ab 'eo bord?", answer: nil, created_at: "2026-04-11T22:36:20.659629Z", updated_at: "2026-04-11T22:36:20.659629Z")
Exercise.create!(id: 293, lesson_id: 14, number: 12, prompt: "Nach 'eo í an chathaoir?", answer: nil, created_at: "2026-04-11T22:36:20.660032Z", updated_at: "2026-04-11T22:36:20.660032Z")
Exercise.create!(id: 294, lesson_id: 14, number: 13, prompt: "Ab 'in iad na daoine a bhí anseo aréir?", answer: nil, created_at: "2026-04-11T22:36:20.660434Z", updated_at: "2026-04-11T22:36:20.660434Z")
Exercise.create!(id: 295, lesson_id: 14, number: 14, prompt: "Ab 'iúd é an duine atá i gceist?", answer: nil, created_at: "2026-04-11T22:36:20.660835Z", updated_at: "2026-04-11T22:36:20.660835Z")
Exercise.create!(id: 296, lesson_id: 14, number: 15, prompt: "Seo í do bhean", answer: nil, created_at: "2026-04-11T22:36:20.661245Z", updated_at: "2026-04-11T22:36:20.661245Z")
Exercise.create!(id: 297, lesson_id: 14, number: 16, prompt: "Sin é an duine a bheas sásta é a dhéanamh", answer: nil, created_at: "2026-04-11T22:36:20.661650Z", updated_at: "2026-04-11T22:36:20.661650Z")
Exercise.create!(id: 298, lesson_id: 14, number: 17, prompt: "Ab 'eo feilm?", answer: nil, created_at: "2026-04-11T22:36:20.662058Z", updated_at: "2026-04-11T22:36:20.662058Z")
Exercise.create!(id: 299, lesson_id: 14, number: 18, prompt: "Ní hin í an fhírinne", answer: nil, created_at: "2026-04-11T22:36:20.662466Z", updated_at: "2026-04-11T22:36:20.662466Z")
Exercise.create!(id: 300, lesson_id: 14, number: 19, prompt: "Ab 'eo í leabhar Máirtín?", answer: nil, created_at: "2026-04-11T22:36:20.662873Z", updated_at: "2026-04-11T22:36:20.662873Z")
Exercise.create!(id: 301, lesson_id: 14, number: 20, prompt: "Ab 'in é an chaoi?", answer: nil, created_at: "2026-04-11T22:36:20.663276Z", updated_at: "2026-04-11T22:36:20.663276Z")
Exercise.create!(id: 302, lesson_id: 14, number: 21, prompt: "Sin teach eile", answer: nil, created_at: "2026-04-11T22:36:20.663680Z", updated_at: "2026-04-11T22:36:20.663680Z")
Exercise.create!(id: 303, lesson_id: 14, number: 22, prompt: "Ab 'eo coirce?", answer: nil, created_at: "2026-04-11T22:36:20.664083Z", updated_at: "2026-04-11T22:36:20.664083Z")
Exercise.create!(id: 304, lesson_id: 14, number: 23, prompt: "There are five or six people here who can understand French.", answer: nil, created_at: "2026-04-11T22:36:20.664554Z", updated_at: "2026-04-11T22:36:20.664554Z")
Exercise.create!(id: 305, lesson_id: 14, number: 24, prompt: "Those there are the three priests who were at the church last Sunday.", answer: nil, created_at: "2026-04-11T22:36:20.665008Z", updated_at: "2026-04-11T22:36:20.665008Z")
Exercise.create!(id: 306, lesson_id: 14, number: 25, prompt: "This here is the young crowd who are willing to do the work. They are able to sow seeds and grow potatoes and oats.", answer: nil, created_at: "2026-04-11T22:36:20.665423Z", updated_at: "2026-04-11T22:36:20.665423Z")
Exercise.create!(id: 307, lesson_id: 14, number: 26, prompt: "It was necessary to go to the old house again last year and to paint the doors and windows and to clean the whole place.", answer: nil, created_at: "2026-04-11T22:36:20.665826Z", updated_at: "2026-04-11T22:36:20.665826Z")
Exercise.create!(id: 308, lesson_id: 14, number: 27, prompt: "There was only one person willing to come.", answer: nil, created_at: "2026-04-11T22:36:20.666260Z", updated_at: "2026-04-11T22:36:20.666260Z")
