Exercise.create!(id: 336, lesson_id: 17, number: 1, prompt: "Fuair m'athair bás anuraidh. Bhí_ mor orm.", answer: nil, created_at: "2026-04-11T22:38:30.219701Z", updated_at: "2026-04-11T22:38:30.219701Z")
Exercise.create!(id: 337, lesson_id: 17, number: 2, prompt: "Fuair mé airgead inné. Bhí orm.", answer: nil, created_at: "2026-04-11T22:38:30.220167Z", updated_at: "2026-04-11T22:38:30.220167Z")
Exercise.create!(id: 338, lesson_id: 17, number: 3, prompt: "Tá máthair Cháit tinn. Tá uirthi a ghoil ag na pictiúir.", answer: nil, created_at: "2026-04-11T22:38:30.221149Z", updated_at: "2026-04-11T22:38:30.221149Z")
Exercise.create!(id: 339, lesson_id: 17, number: 4, prompt: "Tá an seomra seo dorcha. An bhfuil oraibh ?", answer: nil, created_at: "2026-04-11T22:38:30.221594Z", updated_at: "2026-04-11T22:38:30.221594Z")
Exercise.create!(id: 340, lesson_id: 17, number: 5, prompt: "Tá go leor bia ann. An bhfuil „ ort ?", answer: nil, created_at: "2026-04-11T22:38:30.222028Z", updated_at: "2026-04-11T22:38:30.222028Z")
Exercise.create!(id: 341, lesson_id: 17, number: 6, prompt: "Tá na gasúir ag briseadh fuinneoga orm. Tá orm.", answer: nil, created_at: "2026-04-11T22:38:30.222448Z", updated_at: "2026-04-11T22:38:30.222448Z")
Exercise.create!(id: 342, lesson_id: 17, number: 7, prompt: "Beidh pictiúr maith anocht. Deir Máirtín go bhfuil air a ghoil aige.", answer: nil, created_at: "2026-04-11T22:38:30.222872Z", updated_at: "2026-04-11T22:38:30.222872Z")
Exercise.create!(id: 343, lesson_id: 17, number: 8, prompt: "Beidh scrúdú acu agus tá orthu.", answer: nil, created_at: "2026-04-11T22:38:30.223336Z", updated_at: "2026-04-11T22:38:30.223336Z")
Exercise.create!(id: 344, lesson_id: 17, number: 9, prompt: "Bhí an lá uafásach te agus bhí orainn.", answer: nil, created_at: "2026-04-11T22:38:30.223779Z", updated_at: "2026-04-11T22:38:30.223779Z")
Exercise.create!(id: 345, lesson_id: 17, number: 10, prompt: "Tá mé ag iarraidh a ghoil abhaile anois mar tá orm.", answer: nil, created_at: "2026-04-11T22:38:30.224248Z", updated_at: "2026-04-11T22:38:30.224248Z")
Exercise.create!(id: 346, lesson_id: 18, number: 1, prompt: "She was fond of the science teacher but she was very keen on languages.", answer: nil, created_at: "2026-04-11T22:39:15.874877Z", updated_at: "2026-04-11T22:39:15.874877Z")
Exercise.create!(id: 347, lesson_id: 18, number: 2, prompt: "The lecturers and the lectures were very bad. As for the exams, they were terrible!", answer: nil, created_at: "2026-04-11T22:39:15.875303Z", updated_at: "2026-04-11T22:39:15.875303Z")
Exercise.create!(id: 348, lesson_id: 18, number: 3, prompt: "I was alone. Were you alone too? It is hard to get to know people at the university.", answer: nil, created_at: "2026-04-11T22:39:15.876033Z", updated_at: "2026-04-11T22:39:15.876033Z")
Exercise.create!(id: 349, lesson_id: 18, number: 4, prompt: "I know Máirtín, but I don't know where he is now.", answer: nil, created_at: "2026-04-11T22:39:15.876440Z", updated_at: "2026-04-11T22:39:15.876440Z")
Exercise.create!(id: 350, lesson_id: 18, number: 5, prompt: "Where are those people from? I am not sure whether they are from France or Spain.", answer: nil, created_at: "2026-04-11T22:39:15.876848Z", updated_at: "2026-04-11T22:39:15.876848Z")
Exercise.create!(id: 351, lesson_id: 18, number: 6, prompt: "I got a letter from America on two consecutive days.", answer: nil, created_at: "2026-04-11T22:39:15.877317Z", updated_at: "2026-04-11T22:39:15.877317Z")
Exercise.create!(id: 352, lesson_id: 18, number: 7, prompt: "There wasn't any noise from them for a while.", answer: nil, created_at: "2026-04-11T22:39:15.877729Z", updated_at: "2026-04-11T22:39:15.877729Z")
Exercise.create!(id: 353, lesson_id: 18, number: 8, prompt: "Turn (pl.) off the radio! Light (pl.) the fire and change your clothes! There are people coming visiting us. I don't know why they are coming now.", answer: nil, created_at: "2026-04-11T22:39:15.878144Z", updated_at: "2026-04-11T22:39:15.878144Z")
Exercise.create!(id: 354, lesson_id: 18, number: 9, prompt: "On what is the book? On the table.", answer: nil, created_at: "2026-04-11T22:39:15.878551Z", updated_at: "2026-04-11T22:39:15.878551Z")
Exercise.create!(id: 355, lesson_id: 18, number: 10, prompt: "Take the book up out of the bag!", answer: nil, created_at: "2026-04-11T22:39:15.880509Z", updated_at: "2026-04-11T22:39:15.880509Z")
Exercise.create!(id: 356, lesson_id: 20, number: 1, prompt: "Sin í an fhuinneog. Ní féidir í a oscailt.", answer: nil, created_at: "2026-04-11T22:41:01.974110Z", updated_at: "2026-04-11T22:41:01.974110Z")
Exercise.create!(id: 357, lesson_id: 20, number: 2, prompt: "Sin é an doras. Is féidir é a oscailt.", answer: nil, created_at: "2026-04-11T22:41:01.974543Z", updated_at: "2026-04-11T22:41:01.974543Z")
Exercise.create!(id: 358, lesson_id: 20, number: 3, prompt: "Tá gloine nua anseo. Ní féidir í a bhriseadh.", answer: nil, created_at: "2026-04-11T22:41:01.974949Z", updated_at: "2026-04-11T22:41:01.974949Z")
Exercise.create!(id: 359, lesson_id: 20, number: 4, prompt: "An bhfuil aithne agat ar an gcailín? Is maith léi ceol.", answer: nil, created_at: "2026-04-11T22:41:01.975674Z", updated_at: "2026-04-11T22:41:01.975674Z")
Exercise.create!(id: 360, lesson_id: 20, number: 5, prompt: "Feicim an máistir thall. Ní maith leis gasúir bheaga.", answer: nil, created_at: "2026-04-11T22:41:01.976076Z", updated_at: "2026-04-11T22:41:01.976076Z")
Exercise.create!(id: 361, lesson_id: 20, number: 6, prompt: "Cá bhfuil an bhean sin? Is maith léi a bheith ag foghlaim teangacha.", answer: nil, created_at: "2026-04-11T22:41:01.976456Z", updated_at: "2026-04-11T22:41:01.976456Z")
Exercise.create!(id: 362, lesson_id: 20, number: 7, prompt: "Ní cuimhne (le) (seisean) an focal sin.", answer: nil, created_at: "2026-04-11T22:41:01.976830Z", updated_at: "2026-04-11T22:41:01.976830Z")
Exercise.create!(id: 363, lesson_id: 20, number: 8, prompt: "Is cuma (le Ruairí) faoin bpolaitíocht.", answer: nil, created_at: "2026-04-11T22:41:01.977205Z", updated_at: "2026-04-11T22:41:01.977205Z")
Exercise.create!(id: 364, lesson_id: 20, number: 9, prompt: "Bhí Micheál mí-mhúinte (leis na daoine sin).", answer: nil, created_at: "2026-04-11T22:41:01.977581Z", updated_at: "2026-04-11T22:41:01.977581Z")
Exercise.create!(id: 365, lesson_id: 20, number: 10, prompt: "Siar (le) (muid) ansin ag an bposta.", answer: nil, created_at: "2026-04-11T22:41:01.979122Z", updated_at: "2026-04-11T22:41:01.979122Z")
Exercise.create!(id: 366, lesson_id: 20, number: 11, prompt: "Nach cuimhne (le) (thusa) an lá sin?", answer: nil, created_at: "2026-04-11T22:41:01.979505Z", updated_at: "2026-04-11T22:41:01.979505Z")
Exercise.create!(id: 367, lesson_id: 20, number: 12, prompt: "Ar fearr (le) (sibh) fanacht anseo?", answer: nil, created_at: "2026-04-11T22:41:01.979882Z", updated_at: "2026-04-11T22:41:01.979882Z")
Exercise.create!(id: 368, lesson_id: 20, number: 13, prompt: "Ní dóigh (le) (mé) go mbeidh an aimsir go maith amárach.", answer: nil, created_at: "2026-04-11T22:41:01.980263Z", updated_at: "2026-04-11T22:41:01.980263Z")
Exercise.create!(id: 369, lesson_id: 20, number: 14, prompt: "Bhí muid ag iarraidh an doras a bhriseadh (leis an spáid).", answer: nil, created_at: "2026-04-11T22:41:01.980639Z", updated_at: "2026-04-11T22:41:01.980639Z")
Exercise.create!(id: 370, lesson_id: 20, number: 15, prompt: "Bhí fearg orm (leis an bhfear eile).", answer: nil, created_at: "2026-04-11T22:41:01.981018Z", updated_at: "2026-04-11T22:41:01.981018Z")
Exercise.create!(id: 371, lesson_id: 20, number: 16, prompt: "Ní maith (le) (Cáit) an teas.", answer: nil, created_at: "2026-04-11T22:41:01.981773Z", updated_at: "2026-04-11T22:41:01.981773Z")
Exercise.create!(id: 372, lesson_id: 20, number: 17, prompt: "For a month now everybody is thinking about the election and talking about politics. I don't like any party. I am not going to cast a vote.", answer: nil, created_at: "2026-04-11T22:41:01.982151Z", updated_at: "2026-04-11T22:41:01.982151Z")
Exercise.create!(id: 373, lesson_id: 20, number: 18, prompt: "We are listening to the radio and looking at the news on the television almost every day. It is hard to say who will win (lit. who will have the victory).", answer: nil, created_at: "2026-04-11T22:41:01.982528Z", updated_at: "2026-04-11T22:41:01.982528Z")
Exercise.create!(id: 374, lesson_id: 20, number: 19, prompt: "All the walls and doors and windows are to be cleaned and painted again this year.", answer: nil, created_at: "2026-04-11T22:41:01.982904Z", updated_at: "2026-04-11T22:41:01.982904Z")
Exercise.create!(id: 375, lesson_id: 20, number: 20, prompt: "I don't remember the night you were here.", answer: nil, created_at: "2026-04-11T22:41:01.983278Z", updated_at: "2026-04-11T22:41:01.983278Z")
Exercise.create!(id: 376, lesson_id: 20, number: 21, prompt: "We don't like the heat. We prefer the cold.", answer: nil, created_at: "2026-04-11T22:41:01.983976Z", updated_at: "2026-04-11T22:41:01.983976Z")
Exercise.create!(id: 377, lesson_id: 20, number: 22, prompt: "Ruairí was horrible to Mícheál. He is jealous of him.", answer: nil, created_at: "2026-04-11T22:41:01.984352Z", updated_at: "2026-04-11T22:41:01.984352Z")
Exercise.create!(id: 378, lesson_id: 20, number: 23, prompt: "Máirtín's back was to the gate and he was smoking a cigarette.", answer: nil, created_at: "2026-04-11T22:41:01.984725Z", updated_at: "2026-04-11T22:41:01.984725Z")
Exercise.create!(id: 379, lesson_id: 20, number: 24, prompt: "Where are you from?", answer: nil, created_at: "2026-04-11T22:41:01.985096Z", updated_at: "2026-04-11T22:41:01.985096Z")
Exercise.create!(id: 380, lesson_id: 21, number: 1, prompt: "Imir cluiche eile amárach.", answer: nil, created_at: "2026-04-11T22:41:56.219883Z", updated_at: "2026-04-11T22:41:56.219883Z")
Exercise.create!(id: 381, lesson_id: 21, number: 2, prompt: "Oscail an doras seo agus dún an doras eile.", answer: nil, created_at: "2026-04-11T22:41:56.220320Z", updated_at: "2026-04-11T22:41:56.220320Z")
Exercise.create!(id: 382, lesson_id: 21, number: 3, prompt: "Breathnaigh ar an leabhar sin agus léigh an ceann seo.", answer: nil, created_at: "2026-04-11T22:41:56.220748Z", updated_at: "2026-04-11T22:41:56.220748Z")
Exercise.create!(id: 383, lesson_id: 21, number: 4, prompt: "Coinnigh an mála. Pacáil ar ball é.", answer: nil, created_at: "2026-04-11T22:41:56.221180Z", updated_at: "2026-04-11T22:41:56.221180Z")
Exercise.create!(id: 384, lesson_id: 21, number: 5, prompt: "Athraigh do chuid éadaí agus glan an teach.", answer: nil, created_at: "2026-04-11T22:41:56.221598Z", updated_at: "2026-04-11T22:41:56.221598Z")
Exercise.create!(id: 385, lesson_id: 21, number: 6, prompt: "Nigh na soithí; ansin fág ar an mbord iad.", answer: nil, created_at: "2026-04-11T22:41:56.222031Z", updated_at: "2026-04-11T22:41:56.222031Z")
Exercise.create!(id: 386, lesson_id: 21, number: 7, prompt: "Glanfaidh sé agus scuabfaidh sé na seomraí uilig.", answer: nil, created_at: "2026-04-11T22:41:56.222450Z", updated_at: "2026-04-11T22:41:56.222450Z")
Exercise.create!(id: 387, lesson_id: 21, number: 8, prompt: "Léifidh siad leabhartha agus foghlaimeoidh siad teangacha.", answer: nil, created_at: "2026-04-11T22:41:56.222885Z", updated_at: "2026-04-11T22:41:56.222885Z")
Exercise.create!(id: 388, lesson_id: 21, number: 9, prompt: "Éistfidh muid leis an raidió agus cuideoidh muid libh ag an am céanna.", answer: nil, created_at: "2026-04-11T22:41:56.223298Z", updated_at: "2026-04-11T22:41:56.223298Z")
Exercise.create!(id: 389, lesson_id: 21, number: 10, prompt: "Nuair a dhéanfas mé cupán tae breathnóidh mé ar an bpáipéar.", answer: nil, created_at: "2026-04-11T22:41:56.223717Z", updated_at: "2026-04-11T22:41:56.223717Z")
Exercise.create!(id: 390, lesson_id: 21, number: 11, prompt: "Nuair a chóireos sí na leapacha beidh sí sásta.", answer: nil, created_at: "2026-04-11T22:41:56.224132Z", updated_at: "2026-04-11T22:41:56.224132Z")
Exercise.create!(id: 391, lesson_id: 21, number: 12, prompt: "Tá (faoi) (mise) teach a thógáil anseo.", answer: nil, created_at: "2026-04-11T22:41:56.224561Z", updated_at: "2026-04-11T22:41:56.224561Z")
Exercise.create!(id: 392, lesson_id: 21, number: 13, prompt: "Faoi dheireadh, fuair muid na bróga (faoin mbord).", answer: nil, created_at: "2026-04-11T22:41:56.224973Z", updated_at: "2026-04-11T22:41:56.224973Z")
Exercise.create!(id: 393, lesson_id: 21, number: 14, prompt: "Tá fás anois (faoi na torthaí) uilig seachas an gabháiste.", answer: nil, created_at: "2026-04-11T22:41:56.225401Z", updated_at: "2026-04-11T22:41:56.225401Z")
Exercise.create!(id: 394, lesson_id: 21, number: 15, prompt: "Tá (faoi) (muide) fanacht anseo go dtí Déardaoin.", answer: nil, created_at: "2026-04-11T22:41:56.225827Z", updated_at: "2026-04-11T22:41:56.225827Z")
Exercise.create!(id: 395, lesson_id: 21, number: 16, prompt: "Mh'anam go raibh siad ag caint faoi 'chuile dhuine seachas (faoi) (sibhse).", answer: nil, created_at: "2026-04-11T22:41:56.226258Z", updated_at: "2026-04-11T22:41:56.226258Z")
Exercise.create!(id: 396, lesson_id: 21, number: 17, prompt: "Caith (faoi) (thú) ar an gcathaoir sin !", answer: nil, created_at: "2026-04-11T22:41:56.226669Z", updated_at: "2026-04-11T22:41:56.226669Z")
Exercise.create!(id: 397, lesson_id: 21, number: 18, prompt: "Bhí mé ag caint le Máirtín (faoi Cháit); beidh sí ag imeacht go Sasana amárach.", answer: nil, created_at: "2026-04-11T22:41:56.227129Z", updated_at: "2026-04-11T22:41:56.227129Z")
Exercise.create!(id: 398, lesson_id: 21, number: 19, prompt: "I will get up early tomorrow. I will wake the children and prepare the breakfast. I am afraid that they will miss the bus again tomorrow.", answer: nil, created_at: "2026-04-11T22:41:56.227550Z", updated_at: "2026-04-11T22:41:56.227550Z")
Exercise.create!(id: 399, lesson_id: 21, number: 20, prompt: "Pádraig was here at Eastertime and she will be here shortly.", answer: nil, created_at: "2026-04-11T22:41:56.227969Z", updated_at: "2026-04-11T22:41:56.227969Z")
Exercise.create!(id: 400, lesson_id: 21, number: 21, prompt: "Let out that water ! I will wash myself and shave myself now. Then I will put on my clothes.", answer: nil, created_at: "2026-04-11T22:41:56.228391Z", updated_at: "2026-04-11T22:41:56.228391Z")
Exercise.create!(id: 401, lesson_id: 21, number: 22, prompt: "Máirtín intended to go to Dublin yesterday. I suppose he will be there now. I will be staying until Sunday.", answer: nil, created_at: "2026-04-11T22:41:56.228806Z", updated_at: "2026-04-11T22:41:56.228806Z")
Exercise.create!(id: 402, lesson_id: 21, number: 23, prompt: "I must go now without delay but put on the kettle and we will drink a drop of tea first.", answer: nil, created_at: "2026-04-11T22:41:56.229223Z", updated_at: "2026-04-11T22:41:56.229223Z")
Exercise.create!(id: 403, lesson_id: 21, number: 24, prompt: "Everybody was satisfied besides you.", answer: nil, created_at: "2026-04-11T22:41:56.229684Z", updated_at: "2026-04-11T22:41:56.229684Z")
Exercise.create!(id: 404, lesson_id: 22, number: 1, prompt: "Ní phósfaidh sé Cáit an bhliain seo chugainn.", answer: nil, created_at: "2026-04-11T22:42:40.371917Z", updated_at: "2026-04-11T22:42:40.371917Z")
Exercise.create!(id: 405, lesson_id: 22, number: 2, prompt: "Osclóidh siad an doras.", answer: nil, created_at: "2026-04-11T22:42:40.372607Z", updated_at: "2026-04-11T22:42:40.372607Z")
Exercise.create!(id: 406, lesson_id: 22, number: 3, prompt: "Ní bhacfaidh tú leis an leabhar sin go fóill.", answer: nil, created_at: "2026-04-11T22:42:40.373088Z", updated_at: "2026-04-11T22:42:40.373088Z")
Exercise.create!(id: 407, lesson_id: 22, number: 4, prompt: "Féadfaidh mé fanacht anseo ar feadh cúpla seachtain.", answer: nil, created_at: "2026-04-11T22:42:40.373503Z", updated_at: "2026-04-11T22:42:40.373503Z")
Exercise.create!(id: 408, lesson_id: 22, number: 5, prompt: "Caillfidh sé an bus, mara ndéanfaidh sé deifir.", answer: nil, created_at: "2026-04-11T22:42:40.373958Z", updated_at: "2026-04-11T22:42:40.373958Z")
Exercise.create!(id: 409, lesson_id: 22, number: 6, prompt: "Ní scuabfaidh sí ná ní nífidh sí éadaí go deo arís.", answer: nil, created_at: "2026-04-11T22:42:40.374456Z", updated_at: "2026-04-11T22:42:40.374456Z")
Exercise.create!(id: 410, lesson_id: 22, number: 7, prompt: "An osclófar na doirse?", answer: nil, created_at: "2026-04-11T22:42:40.374923Z", updated_at: "2026-04-11T22:42:40.374923Z")
Exercise.create!(id: 411, lesson_id: 22, number: 8, prompt: "Labhróidh mé leis arís amárach.", answer: nil, created_at: "2026-04-11T22:42:40.375402Z", updated_at: "2026-04-11T22:42:40.375402Z")
Exercise.create!(id: 412, lesson_id: 22, number: 9, prompt: "Suífidh siad síos.", answer: nil, created_at: "2026-04-11T22:42:40.375878Z", updated_at: "2026-04-11T22:42:40.375878Z")
Exercise.create!(id: 413, lesson_id: 22, number: 10, prompt: "Fliuchfaidh tú an tae.", answer: nil, created_at: "2026-04-11T22:42:40.376372Z", updated_at: "2026-04-11T22:42:40.376372Z")
Exercise.create!(id: 414, lesson_id: 22, number: 11, prompt: "Brisfear an t-adhmad.", answer: nil, created_at: "2026-04-11T22:42:40.376867Z", updated_at: "2026-04-11T22:42:40.376867Z")
Exercise.create!(id: 415, lesson_id: 22, number: 12, prompt: "Salófar an cóta.", answer: nil, created_at: "2026-04-11T22:42:40.377354Z", updated_at: "2026-04-11T22:42:40.377354Z")
Exercise.create!(id: 416, lesson_id: 23, number: 1, prompt: "The sun is shining every day.", answer: nil, created_at: "2026-04-11T22:43:27.871942Z", updated_at: "2026-04-11T22:43:27.871942Z")
Exercise.create!(id: 417, lesson_id: 23, number: 2, prompt: "He is practicing his Irish every day.", answer: nil, created_at: "2026-04-11T22:43:27.872364Z", updated_at: "2026-04-11T22:43:27.872364Z")
Exercise.create!(id: 418, lesson_id: 23, number: 3, prompt: "I am washing dishes and making beds every day.", answer: nil, created_at: "2026-04-11T22:43:27.872768Z", updated_at: "2026-04-11T22:43:27.872768Z")
Exercise.create!(id: 419, lesson_id: 23, number: 4, prompt: "She is looking well every day.", answer: nil, created_at: "2026-04-11T22:43:27.873167Z", updated_at: "2026-04-11T22:43:27.873167Z")
Exercise.create!(id: 420, lesson_id: 23, number: 5, prompt: "They are opening windows and closing doors every day.", answer: nil, created_at: "2026-04-11T22:43:27.873565Z", updated_at: "2026-04-11T22:43:27.873565Z")
Exercise.create!(id: 421, lesson_id: 23, number: 6, prompt: "I am reading books but I am not tired every day.", answer: nil, created_at: "2026-04-11T22:43:27.874248Z", updated_at: "2026-04-11T22:43:27.874248Z")
Exercise.create!(id: 422, lesson_id: 23, number: 7, prompt: "I am avoiding Dublin every day.", answer: nil, created_at: "2026-04-11T22:43:27.874655Z", updated_at: "2026-04-11T22:43:27.874655Z")
Exercise.create!(id: 423, lesson_id: 23, number: 8, prompt: "We almost fell on the way home.", answer: nil, created_at: "2026-04-11T22:43:27.875058Z", updated_at: "2026-04-11T22:43:27.875058Z")
Exercise.create!(id: 424, lesson_id: 23, number: 9, prompt: "It is not worth it for me to go there now.", answer: nil, created_at: "2026-04-11T22:43:27.875463Z", updated_at: "2026-04-11T22:43:27.875463Z")
Exercise.create!(id: 425, lesson_id: 23, number: 10, prompt: "Will you write another letter to that man?", answer: nil, created_at: "2026-04-11T22:43:27.875864Z", updated_at: "2026-04-11T22:43:27.875864Z")
Exercise.create!(id: 426, lesson_id: 23, number: 11, prompt: "It is not necessary for you to give money to Cáit.", answer: nil, created_at: "2026-04-11T22:43:27.876268Z", updated_at: "2026-04-11T22:43:27.876268Z")
Exercise.create!(id: 427, lesson_id: 23, number: 12, prompt: "We were trying to show the room to Cáit.", answer: nil, created_at: "2026-04-11T22:43:27.876690Z", updated_at: "2026-04-11T22:43:27.876690Z")
Exercise.create!(id: 428, lesson_id: 23, number: 13, prompt: "That is the thing you should do.", answer: nil, created_at: "2026-04-11T22:43:27.877093Z", updated_at: "2026-04-11T22:43:27.877093Z")
Exercise.create!(id: 429, lesson_id: 23, number: 14, prompt: "I swear he does not help people themselves.", answer: nil, created_at: "2026-04-11T22:43:27.877677Z", updated_at: "2026-04-11T22:43:27.877677Z")
Exercise.create!(id: 430, lesson_id: 23, number: 15, prompt: "It is true for you. The nail is not suitable for the wall.", answer: nil, created_at: "2026-04-11T22:43:27.878076Z", updated_at: "2026-04-11T22:43:27.878076Z")
Exercise.create!(id: 431, lesson_id: 24, number: 1, prompt: "I used not to feel like raising my head off the pillow.", answer: nil, created_at: "2026-04-11T22:44:15.245669Z", updated_at: "2026-04-11T22:44:15.245669Z")
Exercise.create!(id: 432, lesson_id: 24, number: 2, prompt: "The sheets and blankets are falling off the bed.", answer: nil, created_at: "2026-04-11T22:44:15.246113Z", updated_at: "2026-04-11T22:44:15.246113Z")
Exercise.create!(id: 433, lesson_id: 24, number: 3, prompt: "The teacher wanted to give the boy a good blow of a stick.", answer: nil, created_at: "2026-04-11T22:44:15.246533Z", updated_at: "2026-04-11T22:44:15.246533Z")
Exercise.create!(id: 434, lesson_id: 24, number: 4, prompt: "We hadn't the (required) time to jump down off the wall before the teacher came.", answer: nil, created_at: "2026-04-11T22:44:15.246948Z", updated_at: "2026-04-11T22:44:15.246948Z")
Exercise.create!(id: 435, lesson_id: 24, number: 5, prompt: "I am tired of everything!", answer: nil, created_at: "2026-04-11T22:44:15.247555Z", updated_at: "2026-04-11T22:44:15.247555Z")
Exercise.create!(id: 436, lesson_id: 24, number: 6, prompt: "Have you a picture of her?", answer: nil, created_at: "2026-04-11T22:44:15.247970Z", updated_at: "2026-04-11T22:44:15.247970Z")
Exercise.create!(id: 437, lesson_id: 24, number: 7, prompt: "Take off your coat, put on your jacket and tie your shoes.", answer: nil, created_at: "2026-04-11T22:44:15.248389Z", updated_at: "2026-04-11T22:44:15.248389Z")
Exercise.create!(id: 438, lesson_id: 24, number: 8, prompt: "Put off the big light and light the lamp.", answer: nil, created_at: "2026-04-11T22:44:15.248800Z", updated_at: "2026-04-11T22:44:15.248800Z")
Exercise.create!(id: 439, lesson_id: 24, number: 9, prompt: "I used always take fright when the car used to stop at the lights.", answer: nil, created_at: "2026-04-11T22:44:15.249209Z", updated_at: "2026-04-11T22:44:15.249209Z")
Exercise.create!(id: 440, lesson_id: 24, number: 10, prompt: "Máirtín used to teach children here too.", answer: nil, created_at: "2026-04-11T22:44:15.249624Z", updated_at: "2026-04-11T22:44:15.249624Z")
Exercise.create!(id: 441, lesson_id: 24, number: 11, prompt: "He used to be very punctilious. Everyone was fed up with him.", answer: nil, created_at: "2026-04-11T22:44:15.250281Z", updated_at: "2026-04-11T22:44:15.250281Z")
Exercise.create!(id: 442, lesson_id: 24, number: 12, prompt: "One (lit. a person) of his sons was at school here too.", answer: nil, created_at: "2026-04-11T22:44:15.250689Z", updated_at: "2026-04-11T22:44:15.250689Z")
Exercise.create!(id: 443, lesson_id: 26, number: 1, prompt: "Shalaigh tú do léine arís.", answer: nil, created_at: "2026-04-11T22:46:04.657948Z", updated_at: "2026-04-11T22:46:04.657948Z")
Exercise.create!(id: 444, lesson_id: 26, number: 2, prompt: "Nigh tú arís ansin í.", answer: nil, created_at: "2026-04-11T22:46:04.658368Z", updated_at: "2026-04-11T22:46:04.658368Z")
Exercise.create!(id: 445, lesson_id: 26, number: 3, prompt: "Níor léigh tú an leabhar sin ariamh.", answer: nil, created_at: "2026-04-11T22:46:04.659139Z", updated_at: "2026-04-11T22:46:04.659139Z")
Exercise.create!(id: 446, lesson_id: 26, number: 4, prompt: "D'oscail tú an fhuinneog.", answer: nil, created_at: "2026-04-11T22:46:04.659535Z", updated_at: "2026-04-11T22:46:04.659535Z")
Exercise.create!(id: 447, lesson_id: 26, number: 5, prompt: "Níor bhris tú an chathaoir.", answer: nil, created_at: "2026-04-11T22:46:04.659912Z", updated_at: "2026-04-11T22:46:04.659912Z")
Exercise.create!(id: 448, lesson_id: 26, number: 6, prompt: "D'imir tú go maith ach tá tú ag éirí ró-ramhar.", answer: nil, created_at: "2026-04-11T22:46:04.660287Z", updated_at: "2026-04-11T22:46:04.660287Z")
Exercise.create!(id: 449, lesson_id: 26, number: 7, prompt: "D'fhoghlaim tú do chuid Gaeilge thall i Meiriceá.", answer: nil, created_at: "2026-04-11T22:46:04.660681Z", updated_at: "2026-04-11T22:46:04.660681Z")
Exercise.create!(id: 450, lesson_id: 26, number: 8, prompt: "Tóigeadh in Éirinn thú.", answer: nil, created_at: "2026-04-11T22:46:04.662334Z", updated_at: "2026-04-11T22:46:04.662334Z")
Exercise.create!(id: 451, lesson_id: 26, number: 9, prompt: "hOsclaiodh an geata arís.", answer: nil, created_at: "2026-04-11T22:46:04.662713Z", updated_at: "2026-04-11T22:46:04.662713Z")
Exercise.create!(id: 452, lesson_id: 26, number: 10, prompt: "Níor glacadh le bean an tsiopa mar chathaoirleach mar tá sí rud beag bodhar.", answer: nil, created_at: "2026-04-11T22:46:04.663106Z", updated_at: "2026-04-11T22:46:04.663106Z")
Exercise.create!(id: 453, lesson_id: 27, number: 1, prompt: "Tá mé ag glanadh an tseomra. Beidh sé glanta gan mórán achair.", answer: nil, created_at: "2026-04-11T22:46:59.654595Z", updated_at: "2026-04-11T22:46:59.654595Z")
Exercise.create!(id: 454, lesson_id: 27, number: 2, prompt: "Tá mé ag péinteáil an doiris. Beidh sé péinteáilte gan mórán achair.", answer: nil, created_at: "2026-04-11T22:46:59.655007Z", updated_at: "2026-04-11T22:46:59.655007Z")
Exercise.create!(id: 455, lesson_id: 27, number: 3, prompt: "Bhí sé ag athrú a sheaicéid. Anois tá an seaicéad athraithe.", answer: nil, created_at: "2026-04-11T22:46:59.655393Z", updated_at: "2026-04-11T22:46:59.655393Z")
Exercise.create!(id: 456, lesson_id: 27, number: 4, prompt: "Bhí siad ag níochán a gcuid éadaí. Tá siad anois nite.", answer: nil, created_at: "2026-04-11T22:46:59.655773Z", updated_at: "2026-04-11T22:46:59.655773Z")
Exercise.create!(id: 457, lesson_id: 27, number: 5, prompt: "Oscail an fhuinneog. Nuair a bhéas an fhuinneog oscailte, ní bheidh an seomra róthe.", answer: nil, created_at: "2026-04-11T22:46:59.656157Z", updated_at: "2026-04-11T22:46:59.656157Z")
Exercise.create!(id: 458, lesson_id: 27, number: 6, prompt: "Tá sé ag dúnadh an phoill. Tá sé beagnach dúnta cheana féin.", answer: nil, created_at: "2026-04-11T22:46:59.656572Z", updated_at: "2026-04-11T22:46:59.656572Z")
Exercise.create!(id: 459, lesson_id: 27, number: 7, prompt: "Bhí litir agat le cur chun bealaigh. An bhfuil sí curtha chun bealaigh fós?", answer: nil, created_at: "2026-04-11T22:46:59.656959Z", updated_at: "2026-04-11T22:46:59.656959Z")
Exercise.create!(id: 460, lesson_id: 27, number: 8, prompt: "Bhí siad ag caint ar theach nua a cheannacht. Anois, faoi dheireadh tá sé ceannaithe.", answer: nil, created_at: "2026-04-11T22:46:59.657346Z", updated_at: "2026-04-11T22:46:59.657346Z")
Exercise.create!(id: 461, lesson_id: 27, number: 9, prompt: "Bhíodh na seandaoine ag ligean tithe chun donacht. Anois tá siad uilig ligthe chun donacht.", answer: nil, created_at: "2026-04-11T22:46:59.657726Z", updated_at: "2026-04-11T22:46:59.657726Z")
Exercise.create!(id: 462, lesson_id: 27, number: 10, prompt: "Bhí sibh ag dó na seanpháipéir. An bhfuil siad uilig dóite?", answer: nil, created_at: "2026-04-11T22:46:59.658106Z", updated_at: "2026-04-11T22:46:59.658106Z")
Exercise.create!(id: 463, lesson_id: 27, number: 11, prompt: "Bhí an t-urlár le scuabadh, ach tá sé scuabtha faoi dheireadh.", answer: nil, created_at: "2026-04-11T22:46:59.658500Z", updated_at: "2026-04-11T22:46:59.658500Z")
Exercise.create!(id: 464, lesson_id: 27, number: 12, prompt: "Níl an obair dodhéanta. Má choinníonn tú do mhisneach, beidh sí déanta anocht.", answer: nil, created_at: "2026-04-11T22:46:59.658883Z", updated_at: "2026-04-11T22:46:59.658883Z")
Exercise.create!(id: 465, lesson_id: 30, number: 1, prompt: "I got up yesterday earlier than usual. I thought that if I waited the shops would be crowded.", answer: nil, created_at: "2026-04-11T22:49:49.126268Z", updated_at: "2026-04-11T22:49:49.126268Z")
Exercise.create!(id: 466, lesson_id: 30, number: 2, prompt: "Often cotton is brighter than wool but cotton gets dirtier more quickly. Wool is usually more lasting.", answer: nil, created_at: "2026-04-11T22:49:49.126657Z", updated_at: "2026-04-11T22:49:49.126657Z")
Exercise.create!(id: 467, lesson_id: 30, number: 3, prompt: "I tried on the suit. The jacket was too narrow around the shoulders. The trousers was shorter than the one I had on. It only came down to my ankles.", answer: nil, created_at: "2026-04-11T22:49:49.127054Z", updated_at: "2026-04-11T22:49:49.127054Z")
Exercise.create!(id: 468, lesson_id: 30, number: 4, prompt: "It would be more correct to keep your money 'for a rainy day'.", answer: nil, created_at: "2026-04-11T22:49:49.127428Z", updated_at: "2026-04-11T22:49:49.127428Z")
Exercise.create!(id: 469, lesson_id: 30, number: 5, prompt: "I never saw a more peculiar kitchen table! It is cleaner than ours but the sun has it split.", answer: nil, created_at: "2026-04-11T22:49:49.127819Z", updated_at: "2026-04-11T22:49:49.127819Z")
Exercise.create!(id: 470, lesson_id: 30, number: 6, prompt: "We call that man Máirtín.", answer: nil, created_at: "2026-04-11T22:49:49.128198Z", updated_at: "2026-04-11T22:49:49.128198Z")
Exercise.create!(id: 471, lesson_id: 30, number: 7, prompt: "Who is in charge of the place?", answer: nil, created_at: "2026-04-11T22:49:49.128591Z", updated_at: "2026-04-11T22:49:49.128591Z")
Exercise.create!(id: 472, lesson_id: 31, number: 1, prompt: "An mba chuma leat dá mbeadh an aimsir go dona?", answer: nil, created_at: "2026-04-11T22:50:30.849720Z", updated_at: "2026-04-11T22:50:30.849720Z")
Exercise.create!(id: 473, lesson_id: 31, number: 2, prompt: "An mba mhaith leat cupán tae?", answer: nil, created_at: "2026-04-11T22:50:30.850164Z", updated_at: "2026-04-11T22:50:30.850164Z")
Exercise.create!(id: 474, lesson_id: 31, number: 3, prompt: "An mba deacair muintir Árann a thuiscint?", answer: nil, created_at: "2026-04-11T22:50:30.850583Z", updated_at: "2026-04-11T22:50:30.850583Z")
Exercise.create!(id: 475, lesson_id: 31, number: 4, prompt: "Arbh éigean duit teach do mháthar a dhíol?", answer: nil, created_at: "2026-04-11T22:50:30.851302Z", updated_at: "2026-04-11T22:50:30.851302Z")
Exercise.create!(id: 476, lesson_id: 31, number: 5, prompt: "Meas tú arbh fhiú a ghabháil ann?", answer: nil, created_at: "2026-04-11T22:50:30.851729Z", updated_at: "2026-04-11T22:50:30.851729Z")
Exercise.create!(id: 477, lesson_id: 31, number: 6, prompt: "Arbh fhearr leat cupán bainne?", answer: nil, created_at: "2026-04-11T22:50:30.852149Z", updated_at: "2026-04-11T22:50:30.852149Z")
Exercise.create!(id: 478, lesson_id: 31, number: 7, prompt: "Dá mba é an dochtúr, an mba cóir dom caint leis?", answer: nil, created_at: "2026-04-11T22:50:30.852588Z", updated_at: "2026-04-11T22:50:30.852588Z")
Exercise.create!(id: 479, lesson_id: 31, number: 8, prompt: "An mba é an ministéir?", answer: nil, created_at: "2026-04-11T22:50:30.853006Z", updated_at: "2026-04-11T22:50:30.853006Z")
Exercise.create!(id: 480, lesson_id: 31, number: 9, prompt: "B'éigean dom seasamh ar bhruach na habhann.", answer: nil, created_at: "2026-04-11T22:50:30.853427Z", updated_at: "2026-04-11T22:50:30.853427Z")
Exercise.create!(id: 481, lesson_id: 31, number: 10, prompt: "B'fhearr le muintir na hAlban an ola a dhíol.", answer: nil, created_at: "2026-04-11T22:50:30.853838Z", updated_at: "2026-04-11T22:50:30.853838Z")
Exercise.create!(id: 482, lesson_id: 31, number: 11, prompt: "B'fhiú an leabhar sin a léamh.", answer: nil, created_at: "2026-04-11T22:50:30.854252Z", updated_at: "2026-04-11T22:50:30.854252Z")
Exercise.create!(id: 483, lesson_id: 31, number: 12, prompt: "Ba dheacair an fear sin a thuiscint.", answer: nil, created_at: "2026-04-11T22:50:30.854893Z", updated_at: "2026-04-11T22:50:30.854893Z")
Exercise.create!(id: 484, lesson_id: 31, number: 13, prompt: "Ba chóir duit litir a scríobh.", answer: nil, created_at: "2026-04-11T22:50:30.855314Z", updated_at: "2026-04-11T22:50:30.855314Z")
