Exercise.create!(id: 512, lesson_id: 35, number: 1, prompt: "Ba mhaith liom go mbeadh an leabhar sin ag Cáit.", answer: nil, created_at: "2026-04-11T22:54:02.354698Z", updated_at: "2026-04-11T22:54:02.354698Z")
Exercise.create!(id: 513, lesson_id: 35, number: 2, prompt: "Ní miste nach bhfuil airgead agam.", answer: nil, created_at: "2026-04-11T22:54:02.355109Z", updated_at: "2026-04-11T22:54:02.355109Z")
Exercise.create!(id: 514, lesson_id: 35, number: 3, prompt: "Dá mbeadh an t-am agam agus dá mbeadh an t-airgead agam, dhéanfainn é.", answer: nil, created_at: "2026-04-11T22:54:02.355507Z", updated_at: "2026-04-11T22:54:02.355507Z")
