Exercise.create!(id: 574, lesson_id: 19, number: 1, prompt: "Life is not that hard now. I am sure that it is not as hard as it used to be.", answer: nil, created_at: "2026-04-11T23:28:12.530920Z", updated_at: "2026-04-11T23:28:12.530920Z")
Exercise.create!(id: 575, lesson_id: 19, number: 2, prompt: "I notice that the winter used to be harder years ago and it was drier too.", answer: nil, created_at: "2026-04-11T23:28:12.531342Z", updated_at: "2026-04-11T23:28:12.531342Z")
Exercise.create!(id: 576, lesson_id: 19, number: 3, prompt: "Bríd is smaller than Cáit. Bairbre is just as small.", answer: nil, created_at: "2026-04-11T23:28:12.531736Z", updated_at: "2026-04-11T23:28:12.531736Z")
Exercise.create!(id: 577, lesson_id: 19, number: 4, prompt: "How small that woman is!", answer: nil, created_at: "2026-04-11T23:28:12.532110Z", updated_at: "2026-04-11T23:28:12.532110Z")
Exercise.create!(id: 578, lesson_id: 19, number: 5, prompt: "Poor Máirtín will have to go away to the west. He is so dissatisfied that Bríd will have to go too.", answer: nil, created_at: "2026-04-11T23:28:12.532476Z", updated_at: "2026-04-11T23:28:12.532476Z")
Exercise.create!(id: 579, lesson_id: 28, number: 1, prompt: "Cloiseann an bhean úd an iomarca scéalta. si inné go raibh Máirtín ag ól arís.", answer: nil, created_at: "2026-04-11T23:29:07.706926Z", updated_at: "2026-04-11T23:29:07.706926Z")
Exercise.create!(id: 580, lesson_id: 28, number: 2, prompt: "Ithim 'chuile short. Is cuma céard a thabharfas tú dhom, mé é.", answer: nil, created_at: "2026-04-11T23:29:07.707373Z", updated_at: "2026-04-11T23:29:07.707373Z")
Exercise.create!(id: 581, lesson_id: 28, number: 3, prompt: "Tháinig Francach inné Sasanach amárach go leor strainséirí anseo 'chuile bhliain.", answer: nil, created_at: "2026-04-11T23:29:07.707750Z", updated_at: "2026-04-11T23:29:07.707750Z")
Exercise.create!(id: 582, lesson_id: 28, number: 4, prompt: "Cé J& leis an mbean sin? Deireann Séamas i gcónaí gur bean an-bhreá í.", answer: nil, created_at: "2026-04-11T23:29:07.708122Z", updated_at: "2026-04-11T23:29:07.708122Z")
Exercise.create!(id: 583, lesson_id: 28, number: 5, prompt: "Eadrainn féin, abair liom cé dúirt tú leis ansin? Nar tú rud ar bith leis? Nach mbeadh sé níos fearr rud eicint a?", answer: nil, created_at: "2026-04-11T23:29:07.708492Z", updated_at: "2026-04-11T23:29:07.708492Z")
Exercise.create!(id: 584, lesson_id: 28, number: 6, prompt: "Beireann an bhó ag an am seo 'chuile bhliain si aréir.", answer: nil, created_at: "2026-04-11T23:29:07.708865Z", updated_at: "2026-04-11T23:29:07.708865Z")
Exercise.create!(id: 585, lesson_id: 28, number: 7, prompt: "Cén áit ar tógadh thú? Ar agus tógadh anseo thú?", answer: nil, created_at: "2026-04-11T23:29:07.709235Z", updated_at: "2026-04-11T23:29:07.709235Z")
Exercise.create!(id: 586, lesson_id: 28, number: 8, prompt: "ar ais anseo arís amárach agus beidh mé in ann airgead a thabhairt dhuit.", answer: nil, created_at: "2026-04-11T23:29:07.709607Z", updated_at: "2026-04-11T23:29:07.709607Z")
Exercise.create!(id: 587, lesson_id: 28, number: 9, prompt: "An sileann tú go dtiocfaidh sé? Ní é.", answer: nil, created_at: "2026-04-11T23:29:07.709975Z", updated_at: "2026-04-11T23:29:07.709975Z")
Exercise.create!(id: 588, lesson_id: 28, number: 10, prompt: "Tear a arís gan mórán achair. Ná bíodh sé i bhfad nó go tú ar ais arís.", answer: nil, created_at: "2026-04-11T23:29:07.710346Z", updated_at: "2026-04-11T23:29:07.710346Z")
Exercise.create!(id: 589, lesson_id: 28, number: 11, prompt: "Beir thusa ar mo mhála ar feadh nóiméad agus féadfaidh tusa ar mo mhaide.", answer: nil, created_at: "2026-04-11T23:29:07.710750Z", updated_at: "2026-04-11T23:29:07.710750Z")
Exercise.create!(id: 590, lesson_id: 28, number: 12, prompt: "Rugús ar an bhfear a ghoid an t-airgead. Is mór an feall nach féidir ar an bhfear eile.", answer: nil, created_at: "2026-04-11T23:29:07.711120Z", updated_at: "2026-04-11T23:29:07.711120Z")
